// Globo «Sapiens» — scienziati, tappe delle idee sulla vita, scenari sulla storia della scoperta dell'evoluzione.
// Formato: vedi SCHEMA.md (SAP.people, SAP.events, SAP.scenari).
var SAP = window.SAP = window.SAP || {species: [], events: [], scenari: [], dispersal: [], hotspots: [], people: [], stats: {}};

// ---------- SAP.people ----------
SAP.people.push(
{id: "aristotele", name: "Aristotele", born: -384, died: -322, nat: "greco",
 t: 0.00237, lat: 39.2, lon: 26.2, place: "Laguna di Kalloni, isola di Lesbo",
 field: "zoologia", idea: "osservare gli animali dal vero",
 text: "Sull'isola di Lesbo osservò e descrisse più di 500 animali, soprattutto pesci, molluschi e uccelli. Capì che i delfini respirano aria e allattano i piccoli, come i mammiferi di terra, e seguì giorno per giorno lo sviluppo del pulcino nell'uovo. Pensava però che i viventi fossero disposti su una «scala» fissa e che alcuni animali nascessero dal fango: idee superate. Il suo metodo, guardare con i propri occhi e classificare, è ancora la base della biologia.",
 work: "Storia degli animali (circa 344 a.C.)",
 places: [[37.98, 23.72, "Atene (Liceo)"], [40.53, 23.75, "Stagira, città natale"]],
 wiki: "Aristotele", wikiEn: "Aristotle"},

{id: "plinio", name: "Plinio il Vecchio", born: 23, died: 79, nat: "romano",
 t: 0.001949, lat: 41.9, lon: 12.49, place: "Roma",
 field: "storia naturale", idea: "un'enciclopedia di tutta la natura",
 text: "Scrisse la Naturalis historia, 37 libri su animali, piante, minerali e medicina: fu l'enciclopedia della natura più letta per più di mille anni. Raccoglieva tutto quello che leggeva o sentiva, perciò accanto a notizie preziose ci sono anche creature fantastiche. Morì nel 79 d.C. a Stabia: comandava la flotta di Miseno e si era avvicinato al Vesuvio in eruzione per osservare e portare soccorso. Oggi gli scienziati controllano le fonti con molta più cura.",
 work: "Naturalis historia (77 d.C.)",
 places: [[45.81, 9.09, "Como, città natale"], [40.7, 14.48, "Stabia, dove morì nel 79"]],
 wiki: "Plinio il Vecchio", wikiEn: "Pliny the Elder"},

{id: "aldrovandi", name: "Ulisse Aldrovandi", born: 1522, died: 1605, nat: "italiano",
 t: 0.000427, lat: 44.497, lon: 11.352, place: "Palazzo Poggi, Bologna",
 field: "storia naturale", idea: "il museo di storia naturale",
 text: "Professore a Bologna, creò uno dei primi musei di storia naturale d'Europa, il suo «teatro di natura», con migliaia di animali, piante, minerali e fossili. Nel 1568 fece nascere l'Orto botanico di Bologna e fece dipingere migliaia di tavole a colori. Nelle sue opere, come l'Ornithologia sugli uccelli, compaiono ancora draghi e mostri accanto ad animali veri. Le sue collezioni si possono vedere ancora oggi a Palazzo Poggi.",
 work: "Ornithologia (1599)",
 wiki: "Ulisse Aldrovandi", wikiEn: "Ulisse Aldrovandi"},

{id: "redi", name: "Francesco Redi", born: 1626, died: 1697, nat: "italiano",
 t: 0.000358, lat: 43.77, lon: 11.25, place: "Firenze",
 field: "biologia sperimentale", idea: "le mosche nascono dalle uova, non dalla carne",
 text: "Medico dei granduchi di Toscana, mise pezzi di carne in vasi aperti e in vasi coperti da una garza. Le larve comparvero solo dove le mosche potevano deporre le uova: la carne marcia non crea vermi da sola. Fu uno dei primi esperimenti con un «controllo», come si fa ancora oggi. Redi però pensava ancora che gli insetti delle galle nascessero dalla pianta: anche i grandi sbagliano.",
 work: "Esperienze intorno alla generazione degl'insetti (1668)",
 places: [[43.72, 10.40, "Pisa"]],
 wiki: "Francesco Redi", wikiEn: "Francesco Redi"},

{id: "malpighi", name: "Marcello Malpighi", born: 1628, died: 1694, nat: "italiano",
 t: 0.000365, lat: 44.494, lon: 11.343, place: "Università di Bologna",
 field: "anatomia microscopica", idea: "i capillari",
 text: "Guardando al microscopio i polmoni di una rana, nel 1661 vide i capillari, i vasi sottilissimi che uniscono arterie e vene. Così completò la scoperta della circolazione del sangue di William Harvey. Studiò anche il baco da seta, lo sviluppo del pulcino e la struttura delle piante. Molte parti del corpo portano ancora il suo nome, come i tubuli malpighiani degli insetti.",
 work: "De pulmonibus (1661)",
 places: [[44.72, 11.15, "Crevalcore, città natale"], [38.19, 15.55, "Messina"]],
 wiki: "Marcello Malpighi", wikiEn: "Marcello Malpighi"},

{id: "hooke", name: "Robert Hooke", born: 1635, died: 1703, nat: "inglese",
 t: 0.000361, lat: 51.515, lon: -0.087, place: "Royal Society, Londra",
 field: "microscopia", idea: "la «cellula»",
 text: "Nel libro Micrographia disegnò ciò che vedeva al microscopio: una pulce gigante, un pidocchio, l'occhio di una mosca. Guardando una fettina di sughero vide tante celle vuote e le chiamò «cells», come le stanzette dei monaci: da qui la parola cellula. Capì anche che i fossili sono resti di esseri viventi del passato. Le sue tavole fecero scoprire a tutti il mondo del molto piccolo.",
 work: "Micrographia (1665)",
 wiki: "Robert Hooke", wikiEn: "Robert Hooke"},

{id: "leeuwenhoek", name: "Antoni van Leeuwenhoek", born: 1632, died: 1723, nat: "olandese",
 t: 0.00035, lat: 52.01, lon: 4.36, place: "Delft",
 field: "microbiologia", idea: "i microbi",
 text: "Era un mercante di stoffe e costruiva da solo microscopi a una lente, potentissimi per l'epoca. Nel 1676 descrisse gli «animaletti» che nuotavano in una goccia d'acqua: protozoi e batteri, mai visti prima. Osservò anche gli spermatozoi e i batteri della placca dei denti. Non aveva studiato all'università, ma la Royal Society di Londra pubblicò centinaia di sue lettere. È considerato il padre della microbiologia.",
 work: "Lettere alla Royal Society (dal 1673)",
 wiki: "Antoni van Leeuwenhoek", wikiEn: "Antonie van Leeuwenhoek"},

{id: "spallanzani", name: "Lazzaro Spallanzani", born: 1729, died: 1799, nat: "italiano",
 t: 0.000258, lat: 45.19, lon: 9.16, place: "Università di Pavia",
 field: "biologia sperimentale", idea: "niente generazione spontanea dei microbi",
 text: "Fece bollire a lungo dei brodi in vasi sigillati: i microbi non comparivano, quindi non nascono dal nulla. Studiò la rigenerazione della coda e delle zampe di tritoni e salamandre e la digestione con i succhi gastrici. Scoprì che i pipistrelli accecati volano senza urtare gli ostacoli; il perché, l'ecolocalizzazione, fu capito solo nel Novecento. Fece anche la prima fecondazione artificiale in un mammifero, una cagna.",
 work: "Saggio di osservazioni microscopiche (1765)",
 places: [[44.6, 10.69, "Scandiano, città natale"]],
 wiki: "Lazzaro Spallanzani", wikiEn: "Lazzaro Spallanzani"},

{id: "linneo", name: "Carl Linnaeus (Linneo)", born: 1707, died: 1778, nat: "svedese",
 t: 0.000291, lat: 59.86, lon: 17.63, place: "Uppsala",
 field: "classificazione", idea: "il nome scientifico in due parole",
 text: "Inventò il sistema dei nomi scientifici in due parole, come Homo sapiens, che usiamo ancora oggi per oltre 2 milioni di specie descritte. Ordinò i viventi in gruppi uno dentro l'altro: regno, classe, ordine, genere, specie. Pensava che le specie fossero fisse e create così: un'idea superata da Darwin. Divise inoltre gli esseri umani in «varietà» descritte con pregiudizi, che furono usati in seguito dal razzismo; la genetica ha mostrato che le razze umane non esistono.",
 work: "Systema Naturae (1735; 10ª edizione 1758)",
 places: [[52.16, 4.49, "Leida (prima edizione del Systema Naturae)"], [67.0, 20.0, "Lapponia (viaggio del 1732)"]],
 wiki: "Carl von Linné", wikiEn: "Carl Linnaeus"},

{id: "buffon", name: "Georges-Louis Leclerc de Buffon", born: 1707, died: 1788, nat: "francese",
 t: 0.000277, lat: 48.844, lon: 2.359, place: "Jardin du Roi, Parigi",
 field: "storia naturale", idea: "la Terra è molto antica",
 text: "Diresse il giardino botanico di Parigi e scrisse una Storia naturale in 36 volumi, letta in tutta Europa. Scaldando sfere di ferro e misurando quanto ci mettevano a raffreddarsi, calcolò che la Terra avesse almeno 75 000 anni: tantissimi per l'epoca (oggi sappiamo che ne ha 4,5 miliardi). Notò che regioni con lo stesso clima ospitano animali diversi: è un principio della biogeografia. Sbagliò invece sostenendo che gli animali americani fossero «degenerati».",
 work: "Histoire naturelle (dal 1749)",
 places: [[47.62, 4.34, "Montbard, Borgogna"]],
 wiki: "Georges-Louis Leclerc de Buffon", wikiEn: "Georges-Louis Leclerc, Comte de Buffon"},

{id: "lamarck", name: "Jean-Baptiste de Lamarck", born: 1744, died: 1829, nat: "francese",
 t: 0.000217, lat: 48.843, lon: 2.361, place: "Muséum national d'histoire naturelle, Parigi",
 field: "evoluzione", idea: "le specie cambiano nel tempo",
 text: "Fu il primo a proporre una teoria completa dell'evoluzione: le specie si trasformano lentamente nel corso del tempo. Studiò gli invertebrati (la parola è sua) e contribuì a diffondere il termine «biologia». Pensava però che i caratteri acquisiti con l'uso, come muscoli più forti, passassero ai figli: questa idea è stata superata dalla genetica. Morì povero e cieco, ma oggi è ricordato come un pioniere.",
 work: "Filosofia zoologica (1809)",
 wiki: "Jean-Baptiste de Lamarck", wikiEn: "Jean-Baptiste Lamarck"},

{id: "cuvier", name: "Georges Cuvier", born: 1769, died: 1832, nat: "francese",
 t: 0.00023, lat: 48.845, lon: 2.357, place: "Muséum national d'histoire naturelle, Parigi",
 field: "paleontologia", idea: "le estinzioni",
 text: "Nel 1796 confrontò gli scheletri di elefanti e mammut e dimostrò che il mammut era una specie diversa, scomparsa: l'estinzione è reale. Fondò l'anatomia comparata e la paleontologia dei vertebrati: da poche ossa sapeva ricostruire un animale intero. Spiegava le estinzioni con grandi catastrofi improvvise e rifiutava l'evoluzione: su questo si sbagliava. Oggi sappiamo che la vita ha attraversato cinque grandi estinzioni di massa.",
 work: "Memoria sulle specie di elefanti viventi e fossili (1796)",
 wiki: "Georges Cuvier", wikiEn: "Georges Cuvier"},

{id: "humboldt", name: "Alexander von Humboldt", born: 1769, died: 1859, nat: "tedesco (prussiano)",
 t: 0.000224, lat: -1.47, lon: -78.82, place: "Chimborazo, Ecuador",
 field: "biogeografia", idea: "la natura come una rete",
 text: "Dal 1799 al 1804 esplorò le Americhe con il botanico Aimé Bonpland: Orinoco, Ande, Cuba, Messico. Nel 1802 salì sul vulcano Chimborazo oltre i 5 800 metri e disegnò come cambiano le piante salendo di quota: nacque la biogeografia. Vide che il disboscamento intorno al lago di Valencia, in Venezuela, cambiava il clima locale: uno dei primi allarmi ambientali. Darwin partì sul Beagle con i suoi libri.",
 work: "Saggio sulla geografia delle piante (1807); Kosmos (1845–1862)",
 places: [[10.46, -64.17, "Cumaná, Venezuela (arrivo, 1799)"], [52.52, 13.40, "Berlino"]],
 wiki: "Alexander von Humboldt", wikiEn: "Alexander von Humboldt"},

{id: "lyell", name: "Charles Lyell", born: 1797, died: 1875, nat: "scozzese",
 t: 0.000196, lat: 51.51, lon: -0.13, place: "Londra",
 field: "geologia", idea: "il tempo profondo",
 text: "Spiegò che montagne e valli si formano lentamente, con le stesse forze che vediamo oggi: erosione, vulcani, terremoti. Per questo la Terra doveva essere antichissima. Studiò anche l'Etna. Darwin lesse i suoi Principi di geologia durante il viaggio del Beagle e capì che c'era abbastanza tempo per l'evoluzione. Lyell accettò l'evoluzione solo più tardi, ma la sostenne apertamente.",
 work: "Principi di geologia (1830–1833)",
 places: [[37.75, 15.0, "Etna, Sicilia"]],
 wiki: "Charles Lyell", wikiEn: "Charles Lyell"},

{id: "darwin", name: "Charles Darwin", born: 1809, died: 1882, nat: "inglese",
 t: 0.000167, lat: 51.33, lon: 0.05, place: "Down House, Kent",
 field: "evoluzione", idea: "selezione naturale",
 text: "Durante il viaggio del Beagle (1831–1836) raccolse fossili, animali e piante; alle Galápagos notò che i fringuelli e i tordi beffeggiatori cambiano da un'isola all'altra. Dopo vent'anni di studi spiegò come le specie si trasformano: sopravvivono e si riproducono di più gli individui adatti all'ambiente. È la selezione naturale. Non conosceva i geni e alcune sue idee sull'ereditarietà erano sbagliate, ma la sua teoria è la base di tutta la biologia di oggi, per esempio per capire i batteri resistenti agli antibiotici.",
 work: "L'origine delle specie (1859)",
 places: [[-0.7, -90.5, "Galápagos"], [52.2, 0.12, "Cambridge"]],
 wiki: "Charles Darwin", wikiEn: "Charles Darwin"},

{id: "wallace", name: "Alfred Russel Wallace", born: 1823, died: 1913, nat: "britannico (gallese)",
 t: 0.000168, lat: 0.79, lon: 127.38, place: "Ternate, Molucche",
 field: "evoluzione e biogeografia", idea: "selezione naturale, linea di Wallace",
 text: "Raccoglitore di insetti e uccelli, viaggiò in Amazzonia e poi per otto anni nell'arcipelago malese, raccogliendo più di 125 000 esemplari. Nel 1858, da Ternate, spedì a Darwin una lettera con la stessa idea della selezione naturale: i loro scritti furono presentati insieme a Londra. Scoprì la «linea di Wallace», un confine invisibile tra Bali e Lombok che separa animali asiatici e australiani. È considerato il padre della biogeografia.",
 work: "L'arcipelago malese (1869)",
 places: [[-3.1, -60.0, "Amazzonia (1848–1852)"], [-8.5, 115.7, "Stretto di Lombok, linea di Wallace"]],
 wiki: "Alfred Russel Wallace", wikiEn: "Alfred Russel Wallace"},

{id: "mendel", name: "Gregor Mendel", born: 1822, died: 1884, nat: "austriaco (Moravia)",
 t: 0.000161, lat: 49.19, lon: 16.59, place: "Abbazia di San Tommaso, Brno",
 field: "genetica", idea: "le leggi dell'ereditarietà",
 text: "Frate agostiniano, nell'orto del monastero incrociò migliaia di piante di pisello tra il 1856 e il 1863. Contando i figli capì che i caratteri passano attraverso «fattori» che non si mescolano, oggi chiamati geni, e trovò rapporti precisi come 3 a 1. Presentò i risultati nel 1865, ma per 34 anni quasi nessuno li capì. Oggi è considerato il fondatore della genetica.",
 work: "Esperimenti sugli ibridi delle piante (1866)",
 wiki: "Gregor Mendel", wikiEn: "Gregor Mendel"},

{id: "pasteur", name: "Louis Pasteur", born: 1822, died: 1895, nat: "francese",
 t: 0.000164, lat: 48.842, lon: 2.344, place: "École normale supérieure, Parigi",
 field: "microbiologia", idea: "la vita nasce solo dalla vita",
 text: "Con i suoi palloni a «collo di cigno» mostrò che un brodo bollito resta pulito se i microbi dell'aria non possono entrare: la generazione spontanea non esiste. Capì che molte malattie e le fermentazioni sono causate da microrganismi. Inventò la pastorizzazione, che usiamo ancora per il latte, e nel 1885 provò su un bambino il vaccino contro la rabbia. Le sue ricerche hanno salvato milioni di vite.",
 work: "Memoria sui corpuscoli organizzati dell'atmosfera (1862)",
 places: [[47.09, 5.49, "Dole, città natale"]],
 wiki: "Louis Pasteur", wikiEn: "Louis Pasteur"},

{id: "haeckel", name: "Ernst Haeckel", born: 1834, died: 1919, nat: "tedesco",
 t: 0.00016, lat: 50.93, lon: 11.59, place: "Università di Jena",
 field: "zoologia ed evoluzione", idea: "ecologia e alberi genealogici della vita",
 text: "Diffuse le idee di Darwin in Germania, inventò la parola «ecologia» (1866) e disegnò i primi grandi alberi genealogici di tutti i viventi. Le sue tavole di radiolari e meduse sono bellissime ancora oggi. Ma alcune idee erano sbagliate: i suoi disegni di embrioni erano ritoccati per sembrare più simili, e la regola che l'embrione «ripete» l'evoluzione è superata. Mise inoltre i popoli umani in una falsa gerarchia, idee poi sfruttate dal razzismo e dal nazionalismo.",
 work: "Morfologia generale degli organismi (1866)",
 wiki: "Ernst Haeckel", wikiEn: "Ernst Haeckel"},

{id: "bates", name: "Henry Walter Bates", born: 1825, died: 1892, nat: "inglese",
 t: 0.000164, lat: -3.35, lon: -64.71, place: "Ega (Tefé), Amazzonia",
 field: "entomologia", idea: "il mimetismo batesiano",
 text: "Partì per l'Amazzonia con Wallace nel 1848 e vi rimase 11 anni, raccogliendo quasi 15 000 specie, 8 000 delle quali nuove per la scienza. Notò che alcune farfalle innocue imitano i colori di farfalle velenose: così i predatori le evitano. Questo «mimetismo batesiano» fu una delle prime prove della selezione naturale, e Darwin ne fu entusiasta. Oggi si studia con la genetica delle ali.",
 work: "Il naturalista sul Rio delle Amazzoni (1863)",
 places: [[-1.46, -48.5, "Belém (Pará)"]],
 wiki: "Henry Walter Bates", wikiEn: "Henry Walter Bates"},

{id: "anning", name: "Mary Anning", born: 1799, died: 1847, nat: "inglese",
 t: 0.000215, lat: 50.72, lon: -2.94, place: "Lyme Regis, Dorset",
 field: "paleontologia", idea: "rettili marini del Giurassico",
 text: "Da ragazza cercava fossili sulle scogliere di Lyme Regis per venderli ai turisti. Con il fratello Joseph trovò il primo ittiosauro completo conosciuto (1811–1812) e nel 1823 il primo plesiosauro completo. Capì che i «sassi del diavolo» (coproliti) erano escrementi fossili. Essendo donna e povera non poté entrare nelle società scientifiche, e altri pubblicarono le sue scoperte senza citarla. Oggi è riconosciuta come una pioniera della paleontologia.",
 work: "Ittiosauro (1811–1812), plesiosauro (1823)",
 wiki: "Mary Anning", wikiEn: "Mary Anning"},

{id: "dubois", name: "Eugène Dubois", born: 1858, died: 1940, nat: "olandese",
 t: 0.000135, lat: -7.37, lon: 111.36, place: "Trinil, Giava",
 field: "paleoantropologia", idea: "l'uomo di Giava",
 text: "Medico militare, partì per le Indie olandesi apposta per cercare l'«anello mancante» tra scimmie e uomini. Nel 1891 a Trinil, sulle rive del fiume Solo, trovò una calotta cranica e l'anno dopo un femore. Lo chiamò Pithecanthropus erectus; oggi è classificato come Homo erectus. Fu il primo fossile umano trovato fuori dall'Europa cercandolo di proposito.",
 work: "Pithecanthropus erectus (1894)",
 wiki: "Eugène Dubois", wikiEn: "Eugène Dubois"},

{id: "de-vries", name: "Hugo de Vries", born: 1848, died: 1935, nat: "olandese",
 t: 0.000126, lat: 52.367, lon: 4.908, place: "Hortus Botanicus, Amsterdam",
 field: "genetica", idea: "riscoperta di Mendel, «mutazione»",
 text: "Nel 1900, insieme a Carl Correns e Erich von Tschermak, riscoprì le leggi di Mendel, dimenticate da 34 anni. Diffuse la parola «mutazione» per i cambiamenti improvvisi ereditari. Pensava però che nuove specie nascessero di colpo con una sola grande mutazione, studiando l'enagra (Oenothera): le sue «mutazioni» erano in realtà rimescolamenti dei cromosomi, e l'idea è superata. Le mutazioni restano la fonte della variabilità su cui agisce la selezione.",
 work: "La teoria della mutazione (1901–1903)",
 wiki: "Hugo de Vries", wikiEn: "Hugo de Vries"},

{id: "morgan", name: "Thomas Hunt Morgan", born: 1866, died: 1945, nat: "statunitense",
 t: 0.000116, lat: 40.807, lon: -73.962, place: "Columbia University, New York",
 field: "genetica", idea: "i geni stanno sui cromosomi",
 text: "Nella «stanza delle mosche» della Columbia University allevava milioni di moscerini della frutta (Drosophila). Nel 1910 trovò un maschio con gli occhi bianchi e, seguendo come il carattere passava ai figli, dimostrò che i geni si trovano sui cromosomi. Il suo allievo Alfred Sturtevant disegnò nel 1913 la prima mappa genetica. Premio Nobel nel 1933; il moscerino è ancora oggi un animale modello nei laboratori.",
 work: "Il meccanismo dell'eredità mendeliana (1915)",
 wiki: "Thomas Hunt Morgan", wikiEn: "Thomas Hunt Morgan"},

{id: "fisher", name: "Ronald Fisher", born: 1890, died: 1962, nat: "inglese",
 t: 0.000096, lat: 51.81, lon: -0.36, place: "Stazione sperimentale di Rothamsted, Harpenden",
 field: "genetica di popolazioni", idea: "Mendel e Darwin vanno d'accordo",
 text: "Matematico geniale, mostrò che le leggi di Mendel spiegano anche le piccole differenze continue, come l'altezza, e che la selezione naturale funziona con i geni. Con J. B. S. Haldane e Sewall Wright fondò la genetica di popolazioni. Inventò metodi statistici usati ancora oggi in tutta la scienza. Fu però un convinto sostenitore dell'eugenetica, idee oggi respinte, e negò a lungo il legame tra fumo e cancro.",
 work: "La teoria genetica della selezione naturale (1930)",
 wiki: "Ronald Fisher", wikiEn: "Ronald Fisher"},

{id: "dobzhansky", name: "Theodosius Dobzhansky", born: 1900, died: 1975, nat: "russo-statunitense",
 t: 0.000089, lat: 34.14, lon: -118.13, place: "Caltech, Pasadena",
 field: "genetica evolutiva", idea: "la sintesi moderna",
 text: "Nato nell'odierna Ucraina, emigrò negli Stati Uniti nel 1927. Studiando i moscerini selvatici dimostrò che le popolazioni naturali sono piene di variabilità genetica, la materia prima dell'evoluzione. Il suo libro del 1937 unì genetica e darwinismo nella «sintesi moderna». Combatté il razzismo e scrisse una frase famosa: «Nulla in biologia ha senso se non alla luce dell'evoluzione» (1973).",
 work: "Genetica e origine delle specie (1937)",
 wiki: "Theodosius Dobzhansky", wikiEn: "Theodosius Dobzhansky"},

{id: "mayr", name: "Ernst Mayr", born: 1904, died: 2005, nat: "tedesco-statunitense",
 t: 0.000084, lat: 40.781, lon: -73.974, place: "American Museum of Natural History, New York",
 field: "evoluzione e ornitologia", idea: "il concetto biologico di specie",
 text: "Da giovane studiò gli uccelli della Nuova Guinea (1928). Definì la specie come un gruppo di popolazioni che possono incrociarsi tra loro e sono isolate dalle altre. Spiegò che spesso nuove specie nascono quando una popolazione resta separata, per esempio su un'isola. Fu uno dei padri della sintesi moderna e visse fino a 100 anni.",
 work: "Sistematica e origine delle specie (1942)",
 places: [[-5.0, 141.0, "Nuova Guinea (1928)"], [42.378, -71.115, "Harvard"]],
 wiki: "Ernst Mayr", wikiEn: "Ernst Mayr"},

{id: "fleming", name: "Alexander Fleming", born: 1881, died: 1955, nat: "scozzese",
 t: 0.000098, lat: 51.517, lon: -0.174, place: "St Mary's Hospital, Londra",
 field: "microbiologia", idea: "la penicillina",
 text: "Nel settembre 1928, tornato dalle vacanze, notò che una muffa (Penicillium) aveva ucciso i batteri in una piastra dimenticata. Chiamò penicillina la sostanza prodotta dalla muffa. Solo negli anni '40 Howard Florey ed Ernst Chain riuscirono a produrla come farmaco; Nobel a tutti e tre nel 1945. Già allora Fleming avvertì che i batteri possono diventare resistenti: è l'evoluzione in azione, uno dei grandi problemi della medicina di oggi.",
 work: "Articolo sulla penicillina (1929)",
 wiki: "Alexander Fleming", wikiEn: "Alexander Fleming"},

{id: "leopold", name: "Aldo Leopold", born: 1887, died: 1948, nat: "statunitense",
 t: 0.000077, lat: 43.47, lon: -89.74, place: "La «baracca», Baraboo, Wisconsin",
 field: "ecologia e conservazione", idea: "l'etica della terra",
 text: "Forestale, all'inizio uccideva lupi e puma pensando di proteggere i cervi; poi capì che senza predatori i cervi distruggono le foreste. Comprò una fattoria rovinata in Wisconsin e la fece rinascere con la famiglia. Nel suo libro più famoso propose l'«etica della terra»: anche suolo, acque, piante e animali fanno parte della nostra comunità. Morì nel 1948 aiutando a spegnere un incendio; il libro uscì l'anno dopo.",
 work: "Almanacco di un mondo semplice (A Sand County Almanac, 1949)",
 wiki: "Aldo Leopold", wikiEn: "Aldo Leopold"},

{id: "mcclintock", name: "Barbara McClintock", born: 1902, died: 1992, nat: "statunitense",
 t: 0.000078, lat: 40.86, lon: -73.47, place: "Cold Spring Harbor Laboratory, New York",
 field: "genetica", idea: "i geni che saltano",
 text: "Studiando i chicchi colorati del mais, alla fine degli anni '40 scoprì che alcuni pezzi di DNA possono spostarsi da un punto all'altro dei cromosomi: i trasposoni, o «geni saltatori». Per decenni pochi le credettero. Nel 1983 ricevette da sola il premio Nobel per la medicina. Oggi sappiamo che quasi metà del nostro genoma deriva da elementi di questo tipo.",
 work: "Trasposizione nel mais (1950–1951)",
 wiki: "Barbara McClintock", wikiEn: "Barbara McClintock"},

{id: "franklin", name: "Rosalind Franklin", born: 1920, died: 1958, nat: "inglese",
 t: 0.000074, lat: 51.511, lon: -0.116, place: "King's College, Londra",
 field: "biologia molecolare", idea: "la «Foto 51» del DNA",
 text: "Esperta di cristallografia a raggi X, nel 1952 con il suo studente Raymond Gosling ottenne la «Foto 51», l'immagine che mostrava la forma a elica del DNA. Maurice Wilkins la mostrò a James Watson senza chiederle il permesso, e i suoi dati aiutarono Watson e Crick a costruire il modello. Morì di tumore a 37 anni, nel 1958, e non ricevette il Nobel del 1962. Studiò anche la struttura dei virus. Oggi il suo contributo è pienamente riconosciuto.",
 work: "Articolo su Nature (25 aprile 1953)",
 wiki: "Rosalind Franklin", wikiEn: "Rosalind Franklin"},

{id: "watson-crick", name: "James Watson e Francis Crick", born: 1916, died: 2025, nat: "statunitense e inglese",
 t: 0.000073, lat: 52.204, lon: 0.118, place: "Laboratorio Cavendish, Cambridge",
 field: "biologia molecolare", idea: "la doppia elica del DNA",
 text: "Nel 1953 a Cambridge Francis Crick (1916–2004) e James Watson (1928–2025) costruirono il modello del DNA a doppia elica, usando anche i dati di Rosalind Franklin. Le due eliche spiegano come i geni si copiano a ogni divisione cellulare. Nobel nel 1962, insieme a Maurice Wilkins. Crick studiò poi il codice genetico; Watson diresse l'inizio del Progetto Genoma Umano, ma per le sue affermazioni razziste e sessiste, prive di base scientifica, perse incarichi e onorificenze nel 2019.",
 work: "Struttura molecolare degli acidi nucleici (1953)",
 wiki: "Francis Crick", wikiEn: "Francis Crick"},

{id: "levi-montalcini", name: "Rita Levi-Montalcini", born: 1909, died: 2012, nat: "italiana",
 t: 0.000074, lat: 38.65, lon: -90.31, place: "Washington University, Saint Louis",
 field: "neurobiologia", idea: "il fattore di crescita nervoso (NGF)",
 text: "Nata a Torino, nel 1938 fu cacciata dall'università dalle leggi razziali perché ebrea: continuò le ricerche sugli embrioni di pollo in un laboratorio allestito in camera da letto. Negli Stati Uniti, all'inizio degli anni '50, scoprì l'NGF, una proteina che fa crescere le cellule nervose. Nel 1986 ricevette il Nobel con Stanley Cohen. Fu senatrice a vita e visse fino a 103 anni.",
 work: "Scoperta dell'NGF (1951–1952)",
 places: [[45.07, 7.69, "Torino"], [41.9, 12.5, "Roma"], [-22.9, -43.2, "Rio de Janeiro"]],
 wiki: "Rita Levi-Montalcini", wikiEn: "Rita Levi-Montalcini"},

{id: "carson", name: "Rachel Carson", born: 1907, died: 1964, nat: "statunitense",
 t: 0.000064, lat: 38.99, lon: -77.03, place: "Silver Spring, Maryland",
 field: "ecologia", idea: "i pesticidi avvelenano la natura",
 text: "Biologa marina e scrittrice, raccontò come il DDT e altri pesticidi si accumulano nelle catene alimentari, uccidono uccelli e pesci e minacciano la salute umana. Il titolo del libro immagina una primavera senza più canti di uccelli. L'industria chimica la attaccò duramente, ma il libro cambiò l'opinione pubblica. Negli Stati Uniti il DDT fu vietato in agricoltura nel 1972: nacque il movimento ambientalista moderno.",
 work: "Primavera silenziosa (1962)",
 wiki: "Rachel Carson", wikiEn: "Rachel Carson"},

{id: "wilson", name: "Edward O. Wilson", born: 1929, died: 2021, nat: "statunitense",
 t: 0.000059, lat: 42.378, lon: -71.116, place: "Università di Harvard",
 field: "ecologia e biodiversità", idea: "biogeografia delle isole, biodiversità",
 text: "Il più grande esperto di formiche del suo tempo. Con Robert MacArthur spiegò perché le isole grandi e vicine alla terraferma ospitano più specie (1967): la teoria vale anche per i parchi e i boschi isolati. Il suo libro sulla sociobiologia (1975) fece molto discutere quando applicò queste idee agli esseri umani. Diffuse la parola «biodiversità» e propose di proteggere metà della Terra per salvare le specie.",
 work: "La teoria della biogeografia insulare (1967)",
 places: [[24.7, -81.0, "Florida Keys (esperimenti sulle isolette di mangrovie)"]],
 wiki: "Edward O. Wilson", wikiEn: "E. O. Wilson"},

{id: "margulis", name: "Lynn Margulis", born: 1938, died: 2011, nat: "statunitense",
 t: 0.000059, lat: 42.35, lon: -71.105, place: "Università di Boston",
 field: "biologia cellulare", idea: "l'endosimbiosi",
 text: "Propose che mitocondri e cloroplasti, le «centrali» delle nostre cellule e di quelle delle piante, fossero un tempo batteri liberi entrati a vivere dentro altre cellule. Il suo articolo del 1967 fu rifiutato da molte riviste. Negli anni successivi il DNA di mitocondri e cloroplasti le diede ragione: oggi è in tutti i libri di biologia. Alcune sue idee più tarde, invece, non sono state accettate dagli altri scienziati.",
 work: "Sull'origine delle cellule che si dividono per mitosi (1967)",
 wiki: "Lynn Margulis", wikiEn: "Lynn Margulis"},

{id: "woese", name: "Carl Woese", born: 1928, died: 2012, nat: "statunitense",
 t: 0.000049, lat: 40.11, lon: -88.23, place: "Università dell'Illinois, Urbana",
 field: "microbiologia evolutiva", idea: "gli Archaea, terzo dominio della vita",
 text: "Confrontò un gene presente in tutti i viventi, quello dell'RNA ribosomiale 16S, per costruire l'albero della vita dei microbi. Nel 1977, con George Fox, scoprì che alcuni microbi che sembravano batteri formavano un gruppo del tutto diverso: gli Archaea. Nel 1990 propose i tre domini: Batteri, Archaea ed Eucarioti. Oggi sappiamo che anche le nostre cellule hanno antenati tra gli Archaea.",
 work: "Struttura filogenetica del dominio dei procarioti (1977)",
 wiki: "Carl Woese", wikiEn: "Carl Woese"},

{id: "lewontin", name: "Richard Lewontin", born: 1929, died: 2021, nat: "statunitense",
 t: 0.000054, lat: 41.788, lon: -87.601, place: "Università di Chicago",
 field: "genetica di popolazioni", idea: "le razze umane non esistono nei geni",
 text: "Nel 1966, con John Hubby, mostrò che le popolazioni naturali hanno moltissima variabilità genetica. Nel 1972 calcolò che circa l'85% delle differenze genetiche tra esseri umani si trova all'interno di ogni popolazione e solo una piccola parte tra le cosiddette «razze». Gli studi sul DNA lo hanno confermato. Criticò sempre l'uso della biologia per giustificare le disuguaglianze.",
 work: "La ripartizione della diversità umana (1972)",
 places: [[42.378, -71.114, "Harvard"]],
 wiki: "Richard Lewontin", wikiEn: "Richard Lewontin"},

{id: "gould", name: "Stephen Jay Gould", born: 1941, died: 2002, nat: "statunitense",
 t: 0.000054, lat: 42.379, lon: -71.114, place: "Museo di zoologia comparata, Harvard",
 field: "paleontologia ed evoluzione", idea: "gli equilibri punteggiati",
 text: "Con Niles Eldredge propose nel 1972 che molte specie restino quasi uguali per milioni di anni e cambino in tempi brevi, quando nascono nuove specie: gli «equilibri punteggiati». È ancora discusso quanto spesso succeda. Nel libro «Intelligenza e pregiudizio» smontò il razzismo scientifico basato sulla misura dei crani. Fu un grande divulgatore: i suoi saggi hanno fatto amare l'evoluzione a milioni di lettori.",
 work: "Equilibri punteggiati (1972); La vita meravigliosa (1989)",
 wiki: "Stephen Jay Gould", wikiEn: "Stephen Jay Gould"},

{id: "kimura", name: "Motoo Kimura", born: 1924, died: 1994, nat: "giapponese",
 t: 0.000058, lat: 35.11, lon: 138.93, place: "Istituto nazionale di genetica, Mishima",
 field: "evoluzione molecolare", idea: "la teoria neutrale",
 text: "Nel 1968 propose che la maggior parte dei cambiamenti nel DNA non sia né utile né dannosa: questi cambiamenti «neutrali» si diffondono o spariscono per caso, per deriva genetica. Fu un grande dibattito con chi vedeva la selezione dappertutto. Grazie alla sua teoria il DNA funziona come un «orologio molecolare» per datare quando si sono separate le specie. La selezione naturale resta però la forza che crea gli adattamenti.",
 work: "Teoria neutrale dell'evoluzione molecolare (1968; libro 1983)",
 wiki: "Motoo Kimura", wikiEn: "Motoo Kimura"},

{id: "ohta", name: "Tomoko Ohta", born: 1933, died: null, nat: "giapponese",
 t: 0.000053, lat: 35.12, lon: 138.95, place: "Istituto nazionale di genetica, Mishima",
 field: "evoluzione molecolare", idea: "la teoria quasi neutrale",
 text: "Collaboratrice di Kimura, nel 1973 propose la teoria «quasi neutrale»: molte mutazioni sono appena un po' dannose, e il loro destino dipende da quanto è grande la popolazione. Nelle popolazioni piccole il caso conta di più e anche mutazioni leggermente dannose possono diffondersi. È importante per capire le specie minacciate, ridotte a pochi individui. Nel 2015 ha ricevuto il premio Crafoord.",
 work: "Sostituzioni di mutanti leggermente dannosi nell'evoluzione (1973)",
 wiki: "Tomoko Ohta", wikiEn: "Tomoko Ohta"},

{id: "leakey", name: "Famiglia Leakey (Louis, Mary, Richard, Meave, Louise)", born: 1903, died: null, nat: "keniota e britannica",
 t: 0.000067, lat: -2.99, lon: 35.35, place: "Gola di Olduvai, Tanzania",
 field: "paleoantropologia", idea: "l'Africa culla dell'umanità",
 text: "Il 17 luglio 1959 Mary Leakey trovò a Olduvai il cranio di Paranthropus boisei; nel 1964 Louis e colleghi descrissero Homo habilis. Nel 1978 Mary scoprì a Laetoli le impronte di ominidi bipedi di 3,6 milioni di anni fa. Il figlio Richard guidò la squadra che nel 1984 trovò il «ragazzo del Turkana» (scoperto da Kamoya Kimeu); Meave e Louise hanno continuato le ricerche. Louis inviò anche Jane Goodall, Dian Fossey e Biruté Galdikas a studiare le grandi scimmie.",
 work: "Scoperte a Olduvai (dal 1959), Laetoli (1978), Turkana (1984)",
 places: [[-3.22, 35.19, "Laetoli"], [3.6, 36.1, "Lago Turkana"], [-1.29, 36.82, "Nairobi"]],
 wiki: "Louis Leakey", wikiEn: "Leakey family"},

{id: "goodall", name: "Jane Goodall", born: 1934, died: 2025, nat: "inglese",
 t: 0.000066, lat: -4.67, lon: 29.63, place: "Parco nazionale di Gombe, Tanzania",
 field: "primatologia", idea: "anche gli scimpanzé usano strumenti",
 text: "Arrivò a Gombe nel 1960, a 26 anni e senza laurea. Pochi mesi dopo vide uno scimpanzé, David Greybeard, usare steli d'erba per «pescare» le termiti: si credeva che solo gli esseri umani usassero strumenti. Diede un nome a ogni scimpanzé e ne descrisse emozioni e personalità. Fondò un istituto e il programma per giovani Roots & Shoots. È morta il 1° ottobre 2025, a 91 anni.",
 work: "Nell'ombra dell'uomo (1971)",
 wiki: "Jane Goodall", wikiEn: "Jane Goodall"},

{id: "fossey", name: "Dian Fossey", born: 1932, died: 1985, nat: "statunitense",
 t: 0.000059, lat: -1.43, lon: 29.53, place: "Centro di ricerca di Karisoke, Ruanda",
 field: "primatologia", idea: "i gorilla di montagna",
 text: "Nel 1967 fondò il centro di Karisoke sui vulcani Virunga per studiare i gorilla di montagna. Mostrò che sono animali pacifici e familiari, non i mostri dei film. Lottò duramente contro i bracconieri; fu uccisa nella sua capanna nel 1985 e il caso non è mai stato chiarito. Grazie alla protezione, oggi i gorilla di montagna sono più di mille e nel 2018 non sono più «in pericolo critico».",
 work: "Gorilla nella nebbia (1983)",
 wiki: "Dian Fossey", wikiEn: "Dian Fossey"},

{id: "galdikas", name: "Biruté Galdikas", born: 1946, died: null, nat: "canadese (di origine lituana)",
 t: 0.000055, lat: -2.74, lon: 111.95, place: "Camp Leakey, Tanjung Puting, Borneo",
 field: "primatologia", idea: "la vita degli oranghi",
 text: "Dal 1971 studia gli oranghi nella foresta di Tanjung Puting, nel Borneo indonesiano: è una delle ricerche sul campo più lunghe mai fatte su un mammifero selvatico. Ha scoperto che una femmina di orango ha un piccolo circa ogni otto anni, uno dei ritmi più lenti tra i mammiferi. Per questo gli oranghi soffrono tantissimo per il taglio delle foreste e le piantagioni di palma da olio. Ha fondato centri per curare e liberare oranghi orfani.",
 work: "Reflections of Eden (1995)",
 wiki: null, wikiEn: "Biruté Galdikas"},

{id: "cavalli-sforza", name: "Luigi Luca Cavalli-Sforza", born: 1922, died: 2018, nat: "italiano",
 t: 0.000032, lat: 37.43, lon: -122.17, place: "Università di Stanford, California",
 field: "genetica delle popolazioni umane", idea: "la storia scritta nei geni",
 text: "Nato a Genova, iniziò studiando i gruppi sanguigni nelle valli dell'Appennino parmense e poi i popoli di tutto il mondo. Con Paolo Menozzi e Alberto Piazza disegnò le mappe genetiche dell'umanità e mostrò che l'albero dei geni somiglia a quello delle lingue. Spiegò che le razze umane non hanno fondamento biologico. Il suo lavoro ha aperto la strada agli studi sul DNA antico.",
 work: "Storia e geografia dei geni umani (1994)",
 places: [[44.8, 10.33, "Parma e il suo Appennino"], [45.19, 9.16, "Pavia"]],
 wiki: "Luigi Luca Cavalli-Sforza", wikiEn: "Luigi Luca Cavalli-Sforza"},

{id: "paabo", name: "Svante Pääbo", born: 1955, died: null, nat: "svedese",
 t: 0.000016, lat: 51.322, lon: 12.396, place: "Istituto Max Planck di antropologia evolutiva, Lipsia",
 field: "paleogenetica", idea: "il DNA dei Neanderthal",
 text: "Ha inventato metodi per leggere il DNA antico, rovinato e mescolato a quello di batteri. Nel 1997 lesse un pezzo di DNA mitocondriale di Neanderthal e nel 2010 il primo genoma quasi completo. Scoprì che chi non ha antenati africani recenti porta circa il 2% di DNA neanderthaliano. Sempre nel 2010, da un ossicino di dito, scoprì i Denisoviani. Premio Nobel per la medicina nel 2022.",
 work: "Bozza del genoma di Neanderthal (2010)",
 places: [[51.4, 84.68, "Grotta di Denisova, Altaj"], [48.14, 11.58, "Monaco di Baviera"]],
 wiki: "Svante Pääbo", wikiEn: "Svante Pääbo"},

{id: "barbujani", name: "Guido Barbujani", born: 1955, died: null, nat: "italiano",
 t: 0.00002, lat: 44.84, lon: 11.62, place: "Università di Ferrara",
 field: "genetica delle popolazioni umane", idea: "le razze sono un'invenzione",
 text: "Nato ad Adria, insegna genetica a Ferrara dal 1996. Con il DNA ha confermato che la maggior parte delle differenze genetiche si trova tra persone dello stesso popolo, non tra popoli diversi. Studia anche il DNA antico, per esempio quello degli Etruschi. Nel libro «L'invenzione delle razze» (2006) spiega ai lettori perché dividere l'umanità in razze non ha basi scientifiche.",
 work: "L'invenzione delle razze (2006)",
 wiki: "Guido Barbujani", wikiEn: "Guido Barbujani"},

{id: "manzi", name: "Giorgio Manzi", born: null, died: null, nat: "italiano",
 t: 0.000011, lat: 41.903, lon: 12.515, place: "Sapienza Università di Roma",
 field: "paleoantropologia", idea: "i fossili umani d'Italia",
 text: "Professore alla Sapienza e direttore del Museo di Antropologia «Giuseppe Sergi», studia il popolamento dell'Europa, i Neanderthal e l'origine di Homo sapiens. Ha ristudiato il cranio di Ceprano, di circa 400 000 anni fa. Nel 2015 ha guidato con David Caramelli lo studio che ha mostrato che l'uomo di Altamura, ancora chiuso nella sua grotta in Puglia, è un Neanderthal di circa 130–170 000 anni fa. Ha partecipato anche alla scoperta di nuove impronte a Laetoli ed è un apprezzato divulgatore.",
 work: "Il grande racconto dell'evoluzione umana (2013)",
 places: [[40.87, 16.57, "Grotta di Lamalunga, Altamura"], [41.55, 13.52, "Ceprano"], [-3.22, 35.19, "Laetoli"]],
 wiki: "Giorgio Manzi", wikiEn: null},

{id: "stringer", name: "Chris Stringer", born: 1947, died: null, nat: "inglese",
 t: 0.000038, lat: 51.496, lon: -0.176, place: "Natural History Museum, Londra",
 field: "paleoantropologia", idea: "l'origine africana recente di Homo sapiens",
 text: "Nel 1988, con Peter Andrews, sostenne che tutti gli esseri umani di oggi discendono da Homo sapiens nati in Africa e poi diffusi nel mondo, sostituendo le altre forme umane. Il DNA gli ha dato in gran parte ragione. Oggi sappiamo però che i sapiens si incrociarono un poco con Neanderthal e Denisoviani, e Stringer ha aggiornato il modello. Studia anche i più antichi abitanti della Gran Bretagna.",
 work: "Prove genetiche e fossili sull'origine degli umani moderni (1988)",
 wiki: null, wikiEn: "Chris Stringer"},

{id: "reich", name: "David Reich", born: 1974, died: null, nat: "statunitense",
 t: 0.000016, lat: 42.336, lon: -71.104, place: "Harvard Medical School, Boston",
 field: "DNA antico", idea: "le migrazioni scritte nei genomi antichi",
 text: "Genetista di popolazioni, ha collaborato agli studi sul genoma di Neanderthal e dei Denisoviani (2010). Il suo laboratorio ha analizzato i genomi di migliaia di persone vissute in passato. Ha mostrato che quasi tutti i popoli di oggi sono il risultato di antichi mescolamenti, per esempio in Europa tra cacciatori, primi agricoltori e pastori delle steppe. Si discute anche dell'etica di questi studi, specialmente sui resti dei popoli indigeni.",
 work: "Chi siamo e come siamo arrivati fin qui (2018)",
 wiki: null, wikiEn: "David Reich (geneticist)"},

{id: "martin", name: "Paul S. Martin", born: 1928, died: 2010, nat: "statunitense",
 t: 0.000059, lat: 32.23, lon: -110.95, place: "Università dell'Arizona, Tucson",
 field: "paleoecologia", idea: "l'ipotesi dell'«overkill»",
 text: "Nel 1967 propose che i grandi mammiferi dell'era glaciale, come mammut, bradipi giganti e cavalli americani, si siano estinti per la caccia degli esseri umani appena arrivati nei continenti. Nel 1973 descrisse una caccia rapidissima, un «blitzkrieg», nelle Americhe. L'idea è ancora discussa: molti studi pensano che abbiano contato insieme caccia e cambiamenti del clima. Propose anche di riportare grandi animali in alcuni territori.",
 work: "Prehistoric overkill (1967)",
 wiki: "Paul S. Martin", wikiEn: "Paul S. Martin"},

{id: "myers", name: "Norman Myers", born: 1934, died: 2019, nat: "britannico",
 t: 0.000038, lat: 51.75, lon: -1.26, place: "Oxford",
 field: "conservazione", idea: "i punti caldi della biodiversità",
 text: "Visse a lungo in Kenya e fu tra i primi a dare l'allarme sulla scomparsa delle foreste tropicali. Nel 1988 propose i «punti caldi» (hotspot) della biodiversità: poche regioni ricchissime di specie che vivono solo lì e molto minacciate. Nel 2000 calcolò che 25 hotspot ospitano il 44% delle piante del mondo. Oggi gli hotspot riconosciuti sono 36 e guidano dove investire per la conservazione.",
 work: "Threatened biotas: «hot spots» in tropical forests (1988)",
 places: [[-1.29, 36.82, "Nairobi, Kenya"]],
 wiki: null, wikiEn: "Norman Myers"},

{id: "attenborough", name: "David Attenborough", born: 1926, died: null, nat: "inglese",
 t: 0.000047, lat: 51.457, lon: -2.6, place: "BBC Natural History Unit, Bristol",
 field: "divulgazione naturalistica", idea: "raccontare la vita sulla Terra",
 text: "Naturalista e autore televisivo, con la serie «La vita sulla Terra» (1979) portò l'evoluzione nelle case di milioni di persone. Da allora ha raccontato quasi ogni ambiente del pianeta. Con «Blue Planet II» (2017) fece conoscere il problema della plastica nei mari. Molte specie, viventi e fossili, portano il suo nome. L'8 maggio 2026 ha compiuto 100 anni.",
 work: "La vita sulla Terra (1979)",
 wiki: "David Attenborough", wikiEn: "David Attenborough"},

{id: "doudna-charpentier", name: "Jennifer Doudna ed Emmanuelle Charpentier", born: 1964, died: null, nat: "statunitense e francese",
 t: 0.000014, lat: 37.87, lon: -122.26, place: "Università della California, Berkeley",
 field: "biologia molecolare", idea: "le «forbici genetiche» CRISPR-Cas9",
 text: "Studiando il sistema con cui i batteri si difendono dai virus, nel 2012 mostrarono che la proteina Cas9 si può «programmare» per tagliare il DNA in un punto preciso. Così si possono correggere i geni in modo semplice e preciso. Nel 2020 vinsero il Nobel per la chimica: per la prima volta due donne condivisero un Nobel scientifico. Nel 2023 è stata approvata la prima cura con CRISPR, per l'anemia falciforme; la modifica di embrioni umani resta invece vietata e molto discussa.",
 work: "Articolo su Science (giugno 2012)",
 places: [[63.82, 20.31, "Umeå, Svezia (laboratorio di Charpentier)"]],
 wiki: "Jennifer Doudna", wikiEn: "Jennifer Doudna"},

{id: "merian", name: "Maria Sibylla Merian", born: 1647, died: 1717, nat: "tedesca",
 t: 0.000321, lat: 5.85, lon: -55.2, place: "Paramaribo, Suriname",
 field: "entomologia e illustrazione", idea: "la metamorfosi degli insetti",
 text: "Pittrice e naturalista, allevava bruchi e disegnava ogni fase: uovo, bruco, crisalide, farfalla, insieme alla pianta di cui si nutrono. Così mostrò che gli insetti non nascono dal fango. A 52 anni partì con la figlia per il Suriname, in Sud America, per studiare gli insetti tropicali (1699–1701). Le sue tavole sono così precise che vengono usate ancora oggi dagli scienziati.",
 work: "Metamorphosis insectorum Surinamensium (1705)",
 places: [[50.11, 8.68, "Francoforte, città natale"], [52.37, 4.9, "Amsterdam"]],
 wiki: "Maria Sibylla Merian", wikiEn: "Maria Sibylla Merian"},

{id: "grassi", name: "Giovanni Battista Grassi", born: 1854, died: 1925, nat: "italiano",
 t: 0.000128, lat: 41.9, lon: 12.51, place: "Università di Roma",
 field: "zoologia e parassitologia", idea: "la zanzara Anopheles trasmette la malaria",
 text: "Nel 1898, con Amico Bignami e Giuseppe Bastianelli, dimostrò che la malaria umana è trasmessa dalle femmine della zanzara Anopheles. L'inglese Ronald Ross lo aveva appena scoperto per la malaria degli uccelli, e il Nobel del 1902 andò solo a Ross, con grandi polemiche. Grassi scoprì anche che i leptocefali sono le larve delle anguille. Le sue ricerche aiutarono a eliminare la malaria dall'Italia, dichiarata libera nel 1970.",
 work: "Studi di uno zoologo sulla malaria (1900)",
 places: [[45.7, 9.05, "Rovellasca, città natale"], [41.88, 12.23, "Maccarese, agro romano"], [40.42, 15.08, "Piana di Capaccio (esperimento del 1900)"]],
 wiki: "Giovanni Battista Grassi", wikiEn: "Giovanni Battista Grassi"},

{id: "dart", name: "Raymond Dart", born: 1893, died: 1988, nat: "australiano",
 t: 0.000102, lat: -27.62, lon: 24.77, place: "Taung, Sudafrica",
 field: "paleoantropologia", idea: "il bambino di Taung, Australopithecus",
 text: "Professore di anatomia a Johannesburg, nel 1924 ricevette da una cava di Taung il cranio fossile di un bambino. Nel 1925 lo chiamò Australopithecus africanus: un antenato con il cervello piccolo ma che camminava eretto. Per vent'anni molti non gli credettero, anche perché il falso «uomo di Piltdown» faceva pensare a un'origine europea con cervello grande. Studi del 2006 mostrano che il bambino fu ucciso da un'aquila. La sua idea di antenati «scimmie assassine» è invece superata.",
 work: "Australopithecus africanus: the man-ape of South Africa (1925)",
 places: [[-26.19, 28.03, "Johannesburg"]],
 wiki: "Raymond Dart", wikiEn: "Raymond Dart"},

{id: "johanson", name: "Donald Johanson", born: 1943, died: null, nat: "statunitense",
 t: 0.000052, lat: 11.1, lon: 40.58, place: "Hadar, Etiopia",
 field: "paleoantropologia", idea: "Lucy, Australopithecus afarensis",
 text: "Il 24 novembre 1974, con lo studente Tom Gray, trovò a Hadar le ossa di Lucy: circa il 40% di uno scheletro di 3,2 milioni di anni fa. Lucy camminava su due gambe ma aveva il cervello piccolo come uno scimpanzé: prima si cammina, poi cresce il cervello. Prese il nome da una canzone dei Beatles che il gruppo ascoltava al campo; in Etiopia è chiamata Dinkinesh. Nel 1978, con Tim White e Yves Coppens, descrisse la specie Australopithecus afarensis.",
 work: "Australopithecus afarensis (1978)",
 places: [[9.04, 38.76, "Museo nazionale d'Etiopia, Addis Abeba"]],
 wiki: "Donald Johanson", wikiEn: "Donald Johanson"},

{id: "oparin-miller", name: "Aleksandr Oparin e Stanley Miller", born: 1894, died: 2007, nat: "russo e statunitense",
 t: 0.000073, lat: 41.79, lon: -87.599, place: "Università di Chicago",
 field: "origine della vita", idea: "il «brodo primordiale»",
 text: "Nel 1924 il russo Aleksandr Oparin (1894–1980) propose che la vita fosse nata da molecole semplici in un oceano primitivo, il «brodo primordiale». Nel 1953 a Chicago lo studente Stanley Miller (1930–2007), con Harold Urey, fece passare scintille elettriche in un miscuglio di gas e acqua: si formarono amminoacidi, i mattoni delle proteine. Oggi si pensa che l'atmosfera antica fosse diversa e si studiano anche le sorgenti calde dei fondali. Come sia nata la vita è ancora una domanda aperta.",
 work: "L'origine della vita (1924); esperimento di Miller-Urey (1953)",
 places: [[55.75, 37.62, "Mosca"]],
 wiki: "Esperimento di Miller-Urey", wikiEn: "Miller–Urey experiment"},

{id: "krause", name: "Johannes Krause", born: 1980, died: null, nat: "tedesco",
 t: 0.000016, lat: 51.323, lon: 12.394, place: "Istituto Max Planck di antropologia evolutiva, Lipsia",
 field: "paleogenetica", idea: "i Denisoviani dal DNA di un dito",
 text: "Nel 2010, con Svante Pääbo, lesse il DNA mitocondriale di un ossicino di dito trovato nella grotta di Denisova, in Siberia: non era né sapiens né Neanderthal. Fu la prima volta che un nuovo gruppo umano veniva scoperto solo grazie al DNA: i Denisoviani. Ha poi letto il genoma del batterio della peste nera del Trecento e ricostruito le migrazioni dei popoli antichi d'Europa. Oggi dirige un dipartimento di archeogenetica a Lipsia.",
 work: "Il genoma mitocondriale di un ominide sconosciuto della Siberia (2010)",
 places: [[51.4, 84.68, "Grotta di Denisova, Altaj"], [48.52, 9.06, "Tubinga"]],
 wiki: "Johannes Krause", wikiEn: "Johannes Krause"},

{id: "fu", name: "Qiaomei Fu", born: 1983, died: null, nat: "cinese",
 t: 0.000009, lat: 39.93, lon: 116.33, place: "Istituto di paleontologia dei vertebrati e paleoantropologia (IVPP), Pechino",
 field: "paleogenetica", idea: "il DNA dei primi sapiens dell'Eurasia",
 text: "Nel laboratorio di Pääbo a Lipsia guidò lo studio del genoma di Ust'-Ishim (2014), un uomo vissuto in Siberia 45 000 anni fa, e quello dell'uomo di Oase in Romania (2015), che aveva un antenato Neanderthal solo 4–6 generazioni prima. Tornata in Cina, ha fondato a Pechino un laboratorio di DNA antico. Nel 2017 ha pubblicato il genoma dell'uomo di Tianyuan, vissuto vicino a Pechino 40 000 anni fa: il più antico DNA umano dell'Asia orientale studiato fino ad allora.",
 work: "Genoma dell'uomo di Tianyuan (2017)",
 places: [[57.7, 71.2, "Ust'-Ishim, Siberia occidentale"], [51.32, 12.4, "Lipsia"], [39.65, 115.88, "Grotta di Tianyuan"]],
 wiki: null, wikiEn: "Qiaomei Fu"},

{id: "skoglund", name: "Pontus Skoglund", born: null, died: null, nat: "svedese",
 t: 0.000014, lat: 59.84, lon: 17.64, place: "Università di Uppsala",
 field: "genomica antica", idea: "i primi agricoltori arrivarono da sud",
 text: "Nel 2012, a Uppsala, confrontò il DNA di agricoltori e di cacciatori-raccoglitori vissuti in Svezia circa 5 000 anni fa: erano popolazioni diverse. L'agricoltura non si diffuse solo come idea, ma insieme a persone arrivate dal sud dell'Europa. Ha poi studiato i primi abitanti delle isole del Pacifico e gli antichi popoli dell'Africa. Oggi dirige il laboratorio di genomica antica del Francis Crick Institute di Londra.",
 work: "Origini e genetica degli agricoltori e dei cacciatori-raccoglitori neolitici in Scandinavia (2012)",
 places: [[51.531, -0.129, "Francis Crick Institute, Londra"]],
 wiki: null, wikiEn: "Pontus Skoglund"},

{id: "willerslev", name: "Eske Willerslev", born: 1971, died: null, nat: "danese",
 t: 0.000016, lat: 55.687, lon: 12.574, place: "Museo di storia naturale, Università di Copenaghen",
 field: "paleogenetica", idea: "il primo genoma di un uomo antico",
 text: "Nel 2010 il suo gruppo lesse il primo genoma completo di un essere umano antico, da un ciuffo di capelli di un uomo della cultura Saqqaq vissuto in Groenlandia circa 4 000 anni fa. È stato anche un pioniere del DNA ambientale, conservato nel terreno e nel ghiaccio. Nel 2022, con il gruppo di Kurt Kjær, ha letto DNA di 2 milioni di anni nei sedimenti di Kap København, in Groenlandia: là vivevano mastodonti e renne, tra foreste. Lavora anche all'Università di Cambridge.",
 work: "Genoma di un antico Paleo-eschimese (2010)",
 places: [[68.9, -51.2, "Groenlandia occidentale (cultura Saqqaq)"], [82.4, -21.0, "Kap København, Groenlandia"], [52.2, 0.12, "Cambridge"]],
 wiki: "Eske Willerslev", wikiEn: "Eske Willerslev"}
);

// ---------- SAP.events (cat «scienza») ----------
SAP.events.push(
{t: 0.000361, t2: null, title: "Micrographia: nasce la parola «cellula»", text: "Robert Hooke pubblica i disegni fatti al microscopio. In una fettina di sughero vede tante piccole celle e le chiama «cells». È l'inizio dello studio delle cellule.", cat: "scienza", lat: 51.515, lon: -0.087, big: false, wiki: null, wikiEn: "Micrographia", sci: ["hooke"]},
{t: 0.000358, t2: null, title: "Redi: le mosche nascono dalle uova", text: "A Firenze Francesco Redi copre con una garza dei vasi con carne: senza mosche non nascono larve. È uno dei primi esperimenti con un controllo contro la generazione spontanea.", cat: "scienza", lat: 43.77, lon: 11.25, big: false, wiki: "Francesco Redi", wikiEn: "Francesco Redi", sci: ["redi"]},
{t: 0.00035, t2: null, title: "Leeuwenhoek scopre i microbi", text: "A Delft Antoni van Leeuwenhoek descrive gli «animaletti» che vede in una goccia d'acqua con i suoi microscopi. Per la prima volta l'umanità vede gli esseri viventi unicellulari.", cat: "scienza", lat: 52.01, lon: 4.36, big: false, wiki: "Antoni van Leeuwenhoek", wikiEn: "Antonie van Leeuwenhoek", sci: ["leeuwenhoek"]},
{t: 0.000291, t2: null, title: "Systema Naturae di Linneo", text: "A Leida esce la prima edizione del Systema Naturae: poche grandi pagine che ordinano piante, animali e minerali. Linneo continuerà ad ampliarlo per tutta la vita.", cat: "scienza", lat: 52.16, lon: 4.49, big: false, wiki: "Systema Naturae", wikiEn: "Systema Naturae", sci: ["linneo"]},
{t: 0.000268, t2: null, title: "10ª edizione del Systema Naturae: i nomi in due parole", text: "Nella 10ª edizione Linneo usa per tutti gli animali il nome in due parole (genere e specie), come Homo sapiens. Per convenzione la nomenclatura zoologica parte da qui: è ancora il sistema che usano i biologi di tutto il mondo.", cat: "scienza", lat: 59.33, lon: 18.07, big: true, wiki: "Nomenclatura binomiale", wikiEn: "10th edition of Systema Naturae", sci: ["linneo"]},
{t: 0.00023, t2: null, title: "Cuvier: le specie si estinguono", text: "A Parigi Georges Cuvier confronta gli scheletri di elefanti e mammut e dimostra che il mammut è una specie scomparsa. Da allora l'estinzione è un fatto scientifico.", cat: "scienza", lat: 48.845, lon: 2.357, big: false, wiki: "Georges Cuvier", wikiEn: "Georges Cuvier", sci: ["cuvier"]},
{t: 0.000227, t2: 0.000222, title: "Humboldt e Bonpland nelle Americhe", text: "Alexander von Humboldt e Aimé Bonpland esplorano Venezuela, Cuba, Ande e Messico. Sul Chimborazo Humboldt descrive come cambiano piante e clima con la quota: nasce la biogeografia.", cat: "scienza", lat: -1.47, lon: -78.82, big: false, wiki: "Alexander von Humboldt", wikiEn: "Alexander von Humboldt", sci: ["humboldt"]},
{t: 0.000217, t2: null, title: "Lamarck: le specie si trasformano", text: "Jean-Baptiste de Lamarck pubblica la Filosofia zoologica, la prima teoria completa dell'evoluzione. Il meccanismo che propone, l'eredità dei caratteri acquisiti, sarà però superato.", cat: "scienza", lat: 48.843, lon: 2.361, big: false, wiki: null, wikiEn: "Philosophie zoologique", sci: ["lamarck"]},
{t: 0.000215, t2: null, title: "Mary Anning e l'ittiosauro", text: "Sulle scogliere di Lyme Regis i fratelli Joseph e Mary Anning trovano lo scheletro di un ittiosauro, un rettile marino del Giurassico. Il mondo scopre animali scomparsi molto diversi da quelli di oggi.", cat: "scienza", lat: 50.72, lon: -2.94, big: false, wiki: "Ichthyosauria", wikiEn: "Ichthyosaur", sci: ["anning"]},
{t: 0.000196, t2: null, title: "Lyell: i Principi di geologia", text: "Charles Lyell spiega che la superficie della Terra cambia lentamente con le forze che vediamo all'opera oggi. La Terra deve essere antichissima: c'è tempo per l'evoluzione.", cat: "scienza", lat: 51.51, lon: -0.13, big: false, wiki: "Principi di geologia", wikiEn: "Principles of Geology", sci: ["lyell"]},
{t: 0.000195, t2: 0.00019, title: "Il viaggio del Beagle", text: "Il giovane Charles Darwin parte da Plymouth sul brigantino Beagle e fa il giro del mondo in quasi cinque anni. In Sud America trova fossili giganti; alle Galápagos (1835) nota che uccelli e tartarughe cambiano da un'isola all'altra.", cat: "scienza", lat: -0.7, lon: -90.5, big: true, wiki: "Secondo viaggio dell'HMS Beagle", wikiEn: "Second voyage of HMS Beagle", sci: ["darwin"]},
{t: 0.00017, t2: null, title: "L'uomo di Neanderthal", text: "Nella valle di Neander, vicino a Düsseldorf, dei cavatori trovano ossa umane strane. Nel 1864 diventeranno una specie a parte, Homo neanderthalensis: è il primo umano estinto riconosciuto.", cat: "scienza", lat: 51.227, lon: 6.95, big: false, wiki: "Neanderthal 1", wikiEn: "Neanderthal 1"},
{t: 0.000168, t2: null, title: "La lettera di Wallace da Ternate", text: "Dalle Molucche Alfred Russel Wallace spedisce a Darwin un saggio con l'idea della selezione naturale. Il 1° luglio 1858 i testi di entrambi vengono letti alla Linnean Society di Londra.", cat: "scienza", lat: 0.79, lon: 127.38, big: false, wiki: "Alfred Russel Wallace", wikiEn: "Alfred Russel Wallace", sci: ["wallace", "darwin"]},
{t: 0.000167, t2: null, title: "L'origine delle specie", text: "Il 24 novembre 1859 esce il libro di Darwin: tutte le specie discendono da antenati comuni e cambiano per selezione naturale. Le copie della prima edizione vanno a ruba. È la base della biologia moderna.", cat: "scienza", lat: 51.33, lon: 0.05, big: true, wiki: "L'origine delle specie", wikiEn: "On the Origin of Species", sci: ["darwin"]},
{t: 0.000164, t2: null, title: "Pasteur e i palloni a collo di cigno", text: "A Parigi Louis Pasteur mostra che un brodo bollito resta senza microbi se la polvere dell'aria non lo raggiunge. La generazione spontanea è sconfitta: la vita nasce dalla vita.", cat: "scienza", lat: 48.842, lon: 2.344, big: false, wiki: "Louis Pasteur", wikiEn: "Louis Pasteur", sci: ["pasteur"]},
{t: 0.000161, t2: 0.00016, title: "Mendel e i piselli", text: "A Brno Gregor Mendel presenta i risultati dei suoi incroci di piselli (1865) e li pubblica (1866): i caratteri passano ai figli tramite «fattori», i geni. Per 34 anni quasi nessuno se ne accorge.", cat: "scienza", lat: 49.19, lon: 16.59, big: true, wiki: "Leggi di Mendel", wikiEn: "Mendelian inheritance", sci: ["mendel"]},
{t: 0.00016, t2: null, title: "Haeckel inventa la parola «ecologia»", text: "A Jena Ernst Haeckel chiama ecologia lo studio dei rapporti tra i viventi e l'ambiente e disegna i primi alberi genealogici di tutta la vita.", cat: "scienza", lat: 50.93, lon: 11.59, big: false, wiki: "Ecologia", wikiEn: "Ecology", sci: ["haeckel"]},
{t: 0.000135, t2: null, title: "L'uomo di Giava", text: "A Trinil, sull'isola di Giava, Eugène Dubois trova la calotta cranica di un ominide antico. Oggi è classificato come Homo erectus: il primo trovato in Asia.", cat: "scienza", lat: -7.37, lon: 111.36, big: false, wiki: "Uomo di Giava", wikiEn: "Java Man", sci: ["dubois"]},
{t: 0.000128, t2: null, title: "Grassi: la zanzara della malaria", text: "A Roma Giovanni Battista Grassi e colleghi dimostrano che la malaria umana è trasmessa dalle zanzare Anopheles. Si apre la strada per combattere la malattia.", cat: "scienza", lat: 41.9, lon: 12.51, big: false, wiki: "Anopheles", wikiEn: "Anopheles", sci: ["grassi"]},
{t: 0.000126, t2: null, title: "Riscoperta delle leggi di Mendel", text: "Hugo de Vries, Carl Correns ed Erich von Tschermak ritrovano, ognuno per conto suo, gli stessi risultati di Mendel. Nasce la genetica.", cat: "scienza", lat: 52.367, lon: 4.908, big: false, wiki: "Hugo de Vries", wikiEn: "Hugo de Vries", sci: ["de-vries", "mendel"]},
{t: 0.000116, t2: null, title: "I geni stanno sui cromosomi", text: "Nella «stanza delle mosche» della Columbia University, Thomas Hunt Morgan studia un moscerino dagli occhi bianchi e dimostra che i geni si trovano sui cromosomi.", cat: "scienza", lat: 40.807, lon: -73.962, big: false, wiki: "Drosophila melanogaster", wikiEn: "Drosophila melanogaster", sci: ["morgan"]},
{t: 0.000102, t2: null, title: "Il bambino di Taung", text: "In Sudafrica Raymond Dart studia il cranio di un piccolo ominide e nel 1925 lo chiama Australopithecus africanus. È la prima prova che l'umanità ha origine in Africa, come aveva previsto Darwin.", cat: "scienza", lat: -27.62, lon: 24.77, big: false, wiki: "Bambino di Taung", wikiEn: "Taung Child", sci: ["dart"]},
{t: 0.000098, t2: null, title: "La penicillina", text: "A Londra Alexander Fleming nota che una muffa uccide i batteri. Dagli anni '40 la penicillina diventa il primo grande antibiotico; ma i batteri, evolvendo, imparano a resisterle.", cat: "scienza", lat: 51.517, lon: -0.174, big: false, wiki: "Penicillina", wikiEn: "Penicillin", sci: ["fleming"]},
{t: 0.000096, t2: 0.000084, title: "La sintesi moderna", text: "Fisher, Haldane, Wright, Dobzhansky, Mayr e altri uniscono la genetica di Mendel e la selezione di Darwin. Nasce la teoria moderna dell'evoluzione, basata sulle popolazioni e sui geni.", cat: "scienza", lat: 40.781, lon: -73.974, big: false, wiki: "Sintesi moderna", wikiEn: "Modern synthesis (20th century)", sci: ["fisher", "dobzhansky", "mayr"]},
{t: 0.000114, t2: 0.000058, title: "Dalla deriva dei continenti alla tettonica a placche", text: "Nel 1912 Alfred Wegener propone che i continenti si muovano, anche perché fossili uguali si trovano in continenti lontani. Le mappe dei fondali di Marie Tharp e gli studi degli anni '60 lo confermano: la tettonica a placche spiega dove vivono piante e animali.", cat: "scienza", lat: 30.0, lon: -42.0, big: false, wiki: "Tettonica delle placche", wikiEn: "Plate tectonics"},
{t: 0.000073, t2: null, title: "La doppia elica del DNA", text: "A Cambridge Watson e Crick pubblicano il modello del DNA, costruito anche grazie alle immagini di Rosalind Franklin. Si capisce come l'informazione ereditaria viene copiata.", cat: "scienza", lat: 52.204, lon: 0.118, big: true, wiki: "DNA", wikiEn: "Molecular Structure of Nucleic Acids", sci: ["watson-crick", "franklin"]},
{t: 0.000073, t2: null, title: "L'esperimento di Miller", text: "A Chicago Stanley Miller ottiene amminoacidi facendo passare scintille in un miscuglio di gas e acqua. Per la prima volta si studia in laboratorio l'origine della vita.", cat: "scienza", lat: 41.79, lon: -87.599, big: false, wiki: "Esperimento di Miller-Urey", wikiEn: "Miller–Urey experiment", sci: ["oparin-miller"]},
{t: 0.000067, t2: null, title: "Olduvai: i fossili dei Leakey", text: "Il 17 luglio 1959 Mary Leakey trova un cranio di Paranthropus boisei nella gola di Olduvai. Nel 1964 lì viene descritto Homo habilis. L'Africa orientale diventa il cuore della ricerca sulle origini umane.", cat: "scienza", lat: -2.99, lon: 35.35, big: false, wiki: "Gola di Olduvai", wikiEn: "Olduvai Gorge", sci: ["leakey"]},
{t: 0.000066, t2: null, title: "Goodall: gli scimpanzé usano strumenti", text: "A Gombe Jane Goodall vede uno scimpanzé che usa steli d'erba per catturare termiti. Cade l'idea che solo gli esseri umani fabbrichino strumenti.", cat: "scienza", lat: -4.67, lon: 29.63, big: false, wiki: "Jane Goodall", wikiEn: "Jane Goodall", sci: ["goodall"]},
{t: 0.000064, t2: null, title: "Primavera silenziosa", text: "Rachel Carson denuncia i danni del DDT e degli altri pesticidi su uccelli, pesci e persone. Il libro fa nascere il movimento ambientalista moderno.", cat: "scienza", lat: 38.99, lon: -77.03, big: false, wiki: "Primavera silenziosa", wikiEn: "Silent Spring", sci: ["carson"]},
{t: 0.000052, t2: null, title: "Lucy", text: "A Hadar, in Etiopia, Donald Johanson e Tom Gray trovano il 40% dello scheletro di un'australopiteca di 3,2 milioni di anni fa. Lucy camminava su due gambe ma aveva un cervello piccolo.", cat: "scienza", lat: 11.1, lon: 40.58, big: true, wiki: "Lucy (paleoantropologia)", wikiEn: "Lucy (Australopithecus)", sci: ["johanson"]},
{t: 0.000049, t2: null, title: "Gli Archaea, terzo dominio della vita", text: "All'Università dell'Illinois Carl Woese e George Fox confrontano l'RNA dei ribosomi e scoprono gli Archaea, microbi diversi sia dai batteri sia da noi. L'albero della vita ha tre grandi rami.", cat: "scienza", lat: 40.11, lon: -88.23, big: false, wiki: "Archaea", wikiEn: "Archaea", sci: ["woese"]},
{t: 0.000048, t2: null, title: "Le impronte di Laetoli", text: "Nella cenere vulcanica di Laetoli la squadra di Mary Leakey scopre impronte lasciate 3,6 milioni di anni fa da ominidi che camminavano eretti.", cat: "scienza", lat: -3.22, lon: 35.19, big: false, wiki: "Laetoli", wikiEn: "Laetoli", sci: ["leakey", "manzi"]},
{t: 0.000039, t2: null, title: "L'«Eva mitocondriale»", text: "Rebecca Cann, Mark Stoneking e Allan Wilson, a Berkeley, confrontano il DNA mitocondriale di persone di tutto il mondo: discende tutto da una donna vissuta in Africa circa 200 000 anni fa. Non era l'unica donna del suo tempo, ma l'unica la cui linea materna è arrivata fino a oggi.", cat: "scienza", lat: 37.87, lon: -122.26, big: false, wiki: "Eva mitocondriale", wikiEn: "Mitochondrial Eve", sci: ["stringer"]},
{t: 0.000025, t2: 0.000004, title: "Il genoma umano", text: "Nel 2001 escono le prime bozze della sequenza del genoma umano, completata quasi del tutto nel 2003 dal Progetto Genoma Umano. Solo nel 2022 il consorzio Telomere-to-Telomere legge davvero tutti i circa 3 miliardi di lettere.", cat: "scienza", lat: 39.0, lon: -77.1, big: true, wiki: "Progetto genoma umano", wikiEn: "Human Genome Project"},
{t: 0.000016, t2: null, title: "Il genoma di Neanderthal", text: "Il gruppo di Svante Pääbo a Lipsia pubblica il genoma dei Neanderthal. Chi ha antenati fuori dall'Africa porta circa il 2% di DNA neanderthaliano: i nostri antenati si sono incrociati con loro.", cat: "scienza", lat: 51.322, lon: 12.396, big: true, wiki: "Svante Pääbo", wikiEn: "Neanderthal genome project", sci: ["paabo", "reich"]},
{t: 0.000016, t2: null, title: "Scoperti i Denisoviani", text: "Dal DNA di un ossicino di dito trovato nella grotta di Denisova, sui monti Altaj, emerge un gruppo umano sconosciuto: i Denisoviani. Parte del loro DNA vive oggi in Asia e in Oceania.", cat: "scienza", lat: 51.4, lon: 84.68, big: false, wiki: "Uomo di Denisova", wikiEn: "Denisovan", sci: ["paabo", "reich"]},
{t: 0.000014, t2: 0.000006, title: "CRISPR: le forbici genetiche", text: "Nel 2012 Jennifer Doudna ed Emmanuelle Charpentier mostrano come usare CRISPR-Cas9 per modificare il DNA in un punto preciso. Nel 2020 vincono il Nobel per la chimica.", cat: "scienza", lat: 37.87, lon: -122.26, big: false, wiki: "CRISPR", wikiEn: "CRISPR gene editing", sci: ["doudna-charpentier"]},
{t: 0.000011, t2: null, title: "Un albero della vita per tutti", text: "Il progetto Open Tree of Life pubblica un primo albero genealogico di 2,3 milioni di specie. Già dal 2012 OneZoom permette di esplorare l'albero della vita come una mappa da ingrandire.", cat: "scienza", lat: 36.0, lon: -78.94, big: false, wiki: "Albero filogenetico", wikiEn: "Open Tree of Life"},
{t: 0.000004, t2: null, title: "Nobel a Svante Pääbo", text: "Il premio Nobel per la medicina 2022 va a Svante Pääbo per le scoperte sui genomi degli ominidi estinti e sull'evoluzione umana. La paleogenetica diventa una scienza riconosciuta da tutti.", cat: "scienza", lat: 59.33, lon: 18.07, big: false, wiki: "Svante Pääbo", wikiEn: "Svante Pääbo", sci: ["paabo"]}
);

